// active reports whether the worker runs this feed.
func (q QueueRow) active() bool {
	return q.Player.Enabled && q.Identity.Enabled && q.Feed.Enabled &&
		q.Feed.Access != model.AccessPrivate && q.Feed.Access != model.AccessUnknown
}

